--// Services
local Players    = game:GetService("Players")
local RunService = game:GetService("RunService")

local LocalPlayer = Players.LocalPlayer
local Camera      = workspace.CurrentCamera

--// ═══════════════════════════════════
--//  Obsidian Library
--// ═══════════════════════════════════
local repo         = "https://raw.githubusercontent.com/deividcomsono/Obsidian/main/"
local Library      = loadstring(game:HttpGet(repo .. "Library.lua"))()
local ThemeManager = loadstring(game:HttpGet(repo .. "addons/ThemeManager.lua"))()
local SaveManager  = loadstring(game:HttpGet(repo .. "addons/SaveManager.lua"))()

local Options = Library.Options
local Toggles = Library.Toggles

Library.ShowToggleFrameInKeybinds = true

local Window = Library:CreateWindow({
    Title            = "ESP  v3",
    Footer           = "Obsidian Edition",
    ShowCustomCursor = true,
    NotifySide       = "Right",
    AutoShow         = true,
})

local Tabs = {
    ESP             = Window:AddTab("ESP",       "eye"),
    Autofarm        = Window:AddTab("Autofarm",  "zap"),
    Visuals         = Window:AddTab("Visuals",   "palette"),
    ["UI Settings"] = Window:AddTab("UI Settings", "settings"),
    Debug           = Window:AddTab("Debug",     "terminal"),
}

--// ═══════════════════════════════════
--//  ESP Tab  ──  Players (Left)
--// ═══════════════════════════════════
local PlayerBox = Tabs.ESP:AddLeftGroupbox("Players", "users")

PlayerBox:AddToggle("ESP_Enabled", {
    Text    = "ESP Enabled",
    Default = true,
    Tooltip = "Master switch – toggles all ESP rendering",
})

PlayerBox:AddDivider()

PlayerBox:AddToggle("ESP_Boxes", {
    Text    = "Boxes",
    Default = true,
    Tooltip = "Bounding box around each player",
})

PlayerBox:AddToggle("ESP_Names", {
    Text    = "Names",
    Default = true,
    Tooltip = "Display name + weapon icon above box",
})

PlayerBox:AddToggle("ESP_Distance", {
    Text    = "Distance",
    Default = true,
    Tooltip = "Distance label below the box",
})

PlayerBox:AddToggle("ESP_Tracers", {
    Text    = "Tracers",
    Default = false,
    Tooltip = "Line from screen bottom-centre to each player",
})

PlayerBox:AddToggle("ESP_Skeleton", {
    Text    = "Skeleton",
    Default = false,
    Tooltip = "Draw bone lines on players within box range",
})

PlayerBox:AddToggle("ESP_FOV", {
    Text    = "FOV Circle",
    Default = false,
    Tooltip = "Awareness ring at the centre of your screen",
})

PlayerBox:AddToggle("ESP_TeamCheck", {
    Text    = "Team Check",
    Default = false,
    Tooltip = "Hide ESP for teammates",
})

PlayerBox:AddDivider()

PlayerBox:AddDropdown("ESP_BoxStyle", {
    Text    = "Box Style",
    Values  = { "Corners", "Full Box", "Dot Only" },
    Default = 1,
    Tooltip = "How the bounding box is drawn",
})

PlayerBox:AddSlider("ESP_MaxDist", {
    Text     = "Max Distance",
    Default  = 1000,
    Min      = 100,
    Max      = 2000,
    Rounding = 0,
    Suffix   = " st",
    Tooltip  = "Beyond this the player is not rendered",
})

PlayerBox:AddSlider("ESP_DotDist", {
    Text     = "Dot Threshold",
    Default  = 120,
    Min      = 20,
    Max      = 500,
    Rounding = 0,
    Suffix   = " st",
    Tooltip  = "Beyond this render as a dot instead of a box",
})

PlayerBox:AddSlider("ESP_FOVRadius", {
    Text     = "FOV Radius",
    Default  = 100,
    Min      = 10,
    Max      = 400,
    Rounding = 0,
    Suffix   = " px",
    Tooltip  = "Radius of the FOV awareness circle (pixels)",
})

--// ═══════════════════════════════════
--//  ESP Tab  ──  Gun Drops (Right)
--// ═══════════════════════════════════
local DropBox = Tabs.ESP:AddRightGroupbox("Gun Drops", "package")

DropBox:AddToggle("Drop_Enabled", {
    Text    = "Drop ESP",
    Default = true,
    Tooltip = "Show ESP on GunDrop parts in workspace",
})

DropBox:AddToggle("Drop_Distance", {
    Text    = "Show Distance",
    Default = true,
    Tooltip = "Distance label on gun drops",
})

DropBox:AddDivider()

DropBox:AddSlider("Drop_MaxDist", {
    Text     = "Max Distance",
    Default  = 500,
    Min      = 50,
    Max      = 2000,
    Rounding = 0,
    Suffix   = " st",
    Tooltip  = "Beyond this drops are not rendered",
})

--// ═══════════════════════════════════
--//  Autofarm Tab
--// ═══════════════════════════════════
local FarmBox  = Tabs.Autofarm:AddLeftGroupbox("Coin Farm",  "zap")
local FarmInfo = Tabs.Autofarm:AddRightGroupbox("Notes", "info")

FarmBox:AddToggle("AF_Enabled", {
    Text    = "Enable Autofarm",
    Default = false,
    Tooltip = "Start / stop the CoinContainer farm loop",
})

FarmBox:AddDropdown("AF_Mode", {
    Text    = "Mode",
    Values  = { "LEGIT", "TWEEN" },
    Default = 1,
    Tooltip = "LEGIT = PathfindingService navigation  |  TWEEN = instant teleport tween",
})

FarmBox:AddDivider()

FarmBox:AddSlider("AF_TweenSpeed", {
    Text     = "Tween Speed",
    Default  = 32,
    Min      = 10,
    Max      = 200,
    Rounding = 0,
    Suffix   = " st/s",
    Tooltip  = "How fast the tween travels (TWEEN mode only) — lower = less ping",
})

FarmBox:AddSlider("AF_WalkSpeed", {
    Text     = "Walk Speed",
    Default  = 16,
    Min      = 16,
    Max      = 32,
    Rounding = 0,
    Tooltip  = "WalkSpeed used in LEGIT mode (vanilla = 16)",
})

FarmBox:AddSlider("AF_CollectDelay", {
    Text     = "Collect Delay",
    Default  = 0.15,
    Min      = 0.05,
    Max      = 1.0,
    Rounding = 2,
    Suffix   = " s",
    Tooltip  = "Pause between collecting each coin (safety buffer)",
})

FarmBox:AddDivider()

FarmBox:AddButton({
    Text    = "Stop & Reset Speed",
    Tooltip = "Disable farm and restore default WalkSpeed",
    Func    = function()
        Toggles.AF_Enabled:SetValue(false)
        local char = LocalPlayer.Character
        local hum  = char and char:FindFirstChildOfClass("Humanoid")
        if hum then hum.WalkSpeed = 16 end
    end,
})

FarmInfo:AddLabel(
    "Targets: CoinContainer\n" ..
    "(auto-detected, loops on\n" ..
    "map reset).\n\n" ..
    "LEGIT — PathfindingService\nwalks through obstacles.\n\n" ..
    "TWEEN — tweens HRP directly\nto each coin (faster).\n\n" ..
    "Collect Delay ≥ 0.1 s is\nrecommended vs kick.",
    true
)

--// ═══════════════════════════════════
--//  Visuals Tab  ──  Box Colours (Left)
--// ═══════════════════════════════════
local ColorsBox = Tabs.Visuals:AddLeftGroupbox("Box Colors", "droplets")

ColorsBox:AddLabel("Knife"):AddColorPicker("Color_Knife", {
    Default = Color3.fromRGB(255, 55, 55),
    Title   = "Knife Color",
})

ColorsBox:AddLabel("Gun"):AddColorPicker("Color_Gun", {
    Default = Color3.fromRGB(255, 215, 50),
    Title   = "Gun Color",
})

ColorsBox:AddLabel("Gun Drop"):AddColorPicker("Color_GunDrop", {
    Default = Color3.fromRGB(255, 135, 0),
    Title   = "Gun Drop Color",
})

ColorsBox:AddLabel("Innocent (unarmed)"):AddColorPicker("Color_Default", {
    Default = Color3.fromRGB(55, 230, 90),
    Title   = "Innocent Color",
})

ColorsBox:AddDivider()

ColorsBox:AddLabel("Tracer"):AddColorPicker("Color_Tracer", {
    Default = Color3.fromRGB(255, 255, 255),
    Title   = "Tracer Color",
})

ColorsBox:AddLabel("Skeleton"):AddColorPicker("Color_Skeleton", {
    Default = Color3.fromRGB(180, 180, 255),
    Title   = "Skeleton Color",
})

ColorsBox:AddLabel("FOV Circle"):AddColorPicker("Color_FOV", {
    Default = Color3.fromRGB(255, 255, 255),
    Title   = "FOV Circle Color",
})

--// ═══════════════════════════════════
--//  Visuals Tab  ──  Distance Colours (Right)
--// ═══════════════════════════════════
local DistBox = Tabs.Visuals:AddRightGroupbox("Distance Colors", "gauge")

DistBox:AddLabel("Close  (0 – 20 st)"):AddColorPicker("DistColor_Close", {
    Default = Color3.fromRGB(255, 70, 70),
    Title   = "Close Distance Color",
})

DistBox:AddLabel("Medium (21 – 60 st)"):AddColorPicker("DistColor_Mid", {
    Default = Color3.fromRGB(255, 210, 0),
    Title   = "Medium Distance Color",
})

DistBox:AddLabel("Far  (61+ st)"):AddColorPicker("DistColor_Far", {
    Default = Color3.fromRGB(160, 255, 180),
    Title   = "Far Distance Color",
