--// ═══════════════════════════════════
--//  Debug Console  (standalone GUI)
--// ═══════════════════════════════════
do
    local StatsService = game:GetService("Stats")

    local MAX_LINES  = 120
    local LOG_COLORS = {
        INFO  = Color3.fromRGB(200, 200, 200),
        OK    = Color3.fromRGB( 80, 220, 100),
        FOUND = Color3.fromRGB( 80, 200, 255),
        WARN  = Color3.fromRGB(255, 200,  50),
        ERROR = Color3.fromRGB(255,  70,  70),
    }

    -- Build the GUI
    local consoleGui = Instance.new("ScreenGui")
    consoleGui.Name           = "ESP_DebugConsole"
    consoleGui.ResetOnSpawn   = false
    consoleGui.IgnoreGuiInset = true
    consoleGui.DisplayOrder   = 9999
    consoleGui.Enabled        = false
    consoleGui.Parent         = gethui and gethui() or game:GetService("CoreGui")

    _G.DebugConsole = consoleGui

    -- Outer frame
    local frame = Instance.new("Frame", consoleGui)
    frame.Size             = UDim2.fromOffset(460, 240)
    frame.Position         = UDim2.new(1, -476, 1, -256)
    frame.BackgroundColor3 = Color3.fromRGB(8, 8, 8)
    frame.BorderSizePixel  = 0
    frame.ClipsDescendants = true
    Instance.new("UICorner", frame).CornerRadius = UDim.new(0, 8)
    local frameStroke = Instance.new("UIStroke", frame)
    frameStroke.Color     = Color3.fromRGB(45, 45, 45)
    frameStroke.Thickness = 1.2

    -- Title bar
    local titleBar = Instance.new("Frame", frame)
    titleBar.Size             = UDim2.new(1, 0, 0, 26)
    titleBar.BackgroundColor3 = Color3.fromRGB(14, 14, 14)
    titleBar.BorderSizePixel  = 0

    local titleLabel = Instance.new("TextLabel", titleBar)
    titleLabel.Size               = UDim2.new(1, -8, 1, 0)
    titleLabel.Position           = UDim2.fromOffset(8, 0)
    titleLabel.BackgroundTransparency = 1
    titleLabel.TextXAlignment     = Enum.TextXAlignment.Left
    titleLabel.Font               = Enum.Font.GothamBold
    titleLabel.TextSize           = 11
    titleLabel.TextColor3         = Color3.fromRGB(180, 180, 180)
    titleLabel.Text               = "◈  DEBUG CONSOLE"

    -- Stats bar (FPS / Ping / Status)
    local statsBar = Instance.new("Frame", frame)
    statsBar.Size             = UDim2.new(1, 0, 0, 20)
    statsBar.Position         = UDim2.fromOffset(0, 26)
    statsBar.BackgroundColor3 = Color3.fromRGB(11, 11, 11)
    statsBar.BorderSizePixel  = 0

    local statsLabel = Instance.new("TextLabel", statsBar)
    statsLabel.Size               = UDim2.new(1, -8, 1, 0)
    statsLabel.Position           = UDim2.fromOffset(8, 0)
    statsLabel.BackgroundTransparency = 1
    statsLabel.TextXAlignment     = Enum.TextXAlignment.Left
    statsLabel.Font               = Enum.Font.Code
    statsLabel.TextSize           = 10
    statsLabel.TextColor3         = Color3.fromRGB(120, 120, 120)
    statsLabel.Text               = "FPS: --   Ping: --ms   Status: Idle"

    -- Divider below stats bar
    local divider = Instance.new("Frame", frame)
    divider.Size             = UDim2.new(1, 0, 0, 1)
    divider.Position         = UDim2.fromOffset(0, 46)
    divider.BackgroundColor3 = Color3.fromRGB(30, 30, 30)
    divider.BorderSizePixel  = 0

    -- Scrolling log area
    local scroll = Instance.new("ScrollingFrame", frame)
    scroll.Size              = UDim2.new(1, 0, 1, -47)
    scroll.Position          = UDim2.fromOffset(0, 47)
    scroll.BackgroundTransparency = 1
    scroll.BorderSizePixel   = 0
    scroll.ScrollBarThickness = 3
    scroll.ScrollBarImageColor3 = Color3.fromRGB(60, 60, 60)
    scroll.CanvasSize        = UDim2.fromOffset(0, 0)
    scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y

    local layout = Instance.new("UIListLayout", scroll)
    layout.Padding   = UDim.new(0, 1)
    layout.SortOrder = Enum.SortOrder.LayoutOrder

    Instance.new("UIPadding", scroll).PaddingLeft = UDim.new(0, 6)

    -- Drag logic
    do
        local UIS2 = game:GetService("UserInputService")
        local dragging  = false
        local dragStart = Vector2.new()
        local startPos  = Vector2.new()

        -- Minimum movement required before a touch counts as a drag (pixels)
        local DRAG_THRESHOLD = 6
        local moved = false

        titleBar.InputBegan:Connect(function(inp)
            if inp.UserInputType == Enum.UserInputType.MouseButton1
            or inp.UserInputType == Enum.UserInputType.Touch then
                dragging  = true
                moved     = false
                dragStart = Vector2.new(inp.Position.X, inp.Position.Y)
                -- AbsolutePosition is always in real pixels, no scale confusion
                startPos  = Vector2.new(frame.AbsolutePosition.X, frame.AbsolutePosition.Y)
            end
        end)

        UIS2.InputChanged:Connect(function(inp)
            if not dragging then return end
            if inp.UserInputType == Enum.UserInputType.MouseMovement
            or inp.UserInputType == Enum.UserInputType.Touch then
                local delta = Vector2.new(inp.Position.X, inp.Position.Y) - dragStart
                if delta.Magnitude < DRAG_THRESHOLD then return end
                moved = true
                frame.Position = UDim2.fromOffset(
                    startPos.X + delta.X,
                    startPos.Y + delta.Y
                )
            end
        end)

        UIS2.InputEnded:Connect(function(inp)
            if inp.UserInputType == Enum.UserInputType.MouseButton1
            or inp.UserInputType == Enum.UserInputType.Touch then
                dragging = false
                moved    = false
            end
        end)
    end

    -- Line counter for layout order
    local lineCount  = 0
    local lineRefs   = {}
    local lastStatus = "Idle"

    -- Log function — always writes to the buffer.
    -- The console's Enabled property controls whether the user sees it.
    local function Log(level, message)
        lineCount = lineCount + 1

        -- Trim oldest line when limit exceeded
        if #lineRefs >= MAX_LINES then
            local oldest = table.remove(lineRefs, 1)
            oldest:Destroy()
        end

        local t      = os.date("%H:%M:%S")
        local prefix = string.format("[%s] [%-5s] ", t, level)

        local row = Instance.new("TextLabel", scroll)
        row.Size               = UDim2.new(1, -12, 0, 14)
        row.BackgroundTransparency = 1
        row.TextXAlignment     = Enum.TextXAlignment.Left
        row.Font               = Enum.Font.Code
        row.TextSize           = 10
        row.TextWrapped        = false
        row.TextColor3         = LOG_COLORS[level] or LOG_COLORS.INFO
        row.Text               = prefix .. tostring(message)
        row.LayoutOrder        = lineCount

        table.insert(lineRefs, row)

        -- Auto-scroll to bottom on next frame so the canvas size has updated
        task.defer(function()
            scroll.CanvasPosition = Vector2.new(0, scroll.AbsoluteCanvasSize.Y)
        end)
    end

    _G.Log = Log

    -- Clear console
    _G.DebugConsoleClear = function()
        for _, ref in ipairs(lineRefs) do ref:Destroy() end
        lineRefs  = {}
        lineCount = 0
    end

    -- FPS / Ping / Status update loop
    task.spawn(function()
        while not Library.Unloaded do
            task.wait(1)

            if not Toggles.Debug_Enabled or not Toggles.Debug_Enabled.Value then continue end

            local fps = math.floor(1 / RunService.RenderStepped:Wait())

            local pingOk, ping = pcall(function()
                return math.floor(
                    game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue()
                )
            end)
            if not pingOk then ping = -1 end

            local fpsStr
            if fps >= 55 then
                fpsStr = string.format("<font color='#50DC64'>%d</font>", fps)
            elseif fps >= 30 then
                fpsStr = string.format("<font color='#FFC832'>%d</font>", fps)
            else
                fpsStr = string.format("<font color='#FF4646'>%d</font>", fps)
            end

            local pingStr
            if ping < 0 then
                pingStr = "<font color='#888888'>N/A</font>"
            elseif ping <= 80 then
                pingStr = string.format("<font color='#50DC64'>%dms</font>", ping)
            elseif ping <= 150 then
                pingStr = string.format("<font color='#FFC832'>%dms</font>", ping)
            else
                pingStr = string.format("<font color='#FF4646'>%dms</font>", ping)
            end

            statsLabel.RichText = true
            statsLabel.Text = string.format(
                "FPS: %s   Ping: %s   Status: %s",
                fpsStr, pingStr, lastStatus
            )
        end
    end)

    -- Keep lastStatus writable from outside
    _G.SetDebugStatus = function(s) lastStatus = s end
end
