local BONE_PAIRS = {
    { "Head",          "UpperTorso"    }, { "Head",          "Torso"           },
    { "UpperTorso",    "LowerTorso"    }, { "Torso",         "HumanoidRootPart"},
    { "UpperTorso",    "LeftUpperArm"  }, { "LeftUpperArm",  "LeftLowerArm"    },
    { "LeftLowerArm",  "LeftHand"      },
    { "UpperTorso",    "RightUpperArm" }, { "RightUpperArm", "RightLowerArm"   },
    { "RightLowerArm", "RightHand"     },
    { "LowerTorso",    "LeftUpperLeg"  }, { "LeftUpperLeg",  "LeftLowerLeg"    },
    { "LeftLowerLeg",  "LeftFoot"      },
    { "LowerTorso",    "RightUpperLeg" }, { "RightUpperLeg", "RightLowerLeg"   },
    { "RightLowerLeg", "RightFoot"     },
    { "Torso", "Left Arm"  }, { "Torso", "Right Arm" },
    { "Torso", "Left Leg"  }, { "Torso", "Right Leg" },
}
local MAX_BONES = #BONE_PAIRS

--// ═══════════════════════════════════
--//  Drawing layer
--// ═══════════════════════════════════
local function newESPData()
    local outline = Drawing.new("Square")
    outline.Thickness = 4; outline.Filled = false
    outline.Color = Color3.new(0,0,0); outline.Visible = false

    local box = Drawing.new("Square")
    box.Thickness = 1.8; box.Filled = false; box.Visible = false

    local corners = {}
    for i = 1, 8 do
        local ln = Drawing.new("Line"); ln.Thickness = 2.2; ln.Visible = false
        corners[i] = ln
    end

    local dot = Drawing.new("Circle")
    dot.Radius = 4; dot.Filled = true; dot.Thickness = 1; dot.Visible = false

    local topLabel = Drawing.new("Text")
    topLabel.Size = 13; topLabel.Center = true; topLabel.Outline = true
    topLabel.Font = Drawing.Fonts.UI; topLabel.Visible = false

    local distLabel = Drawing.new("Text")
    distLabel.Size = 11; distLabel.Center = true; distLabel.Outline = true
    distLabel.Font = Drawing.Fonts.UI; distLabel.Visible = false

    local tracer = Drawing.new("Line"); tracer.Thickness = 1.2; tracer.Visible = false

    local skeleton = {}
    for i = 1, MAX_BONES do
        local ln = Drawing.new("Line"); ln.Thickness = 1.2; ln.Visible = false
        skeleton[i] = ln
    end

    return {
        Outline   = outline,  Box       = box,       Corners   = corners,
        Dot       = dot,      TopLabel  = topLabel,   DistLabel = distLabel,
        Tracer    = tracer,   Skeleton  = skeleton,
    }
end

local function removeESPData(d)
    d.Outline:Remove(); d.Box:Remove(); d.Dot:Remove()
    d.TopLabel:Remove(); d.DistLabel:Remove(); d.Tracer:Remove()
    for _, ln in ipairs(d.Corners)  do ln:Remove() end
    for _, ln in ipairs(d.Skeleton) do ln:Remove() end
end

local function hideAll(d)
    d.Outline.Visible = false; d.Box.Visible     = false
    d.Dot.Visible     = false; d.TopLabel.Visible = false
    d.DistLabel.Visible = false; d.Tracer.Visible = false
    for _, ln in ipairs(d.Corners)  do ln.Visible = false end
    for _, ln in ipairs(d.Skeleton) do ln.Visible = false end
end

local function drawCorners(c, x, y, w, h, color)
    local bx = math.max(6, math.floor(w * 0.20))
    local by = math.max(5, math.floor(h * 0.12))
    c[1].From=Vector2.new(x,y)      c[1].To=Vector2.new(x+bx,y)
    c[2].From=Vector2.new(x,y)      c[2].To=Vector2.new(x,y+by)
    c[3].From=Vector2.new(x+w,y)    c[3].To=Vector2.new(x+w-bx,y)
    c[4].From=Vector2.new(x+w,y)    c[4].To=Vector2.new(x+w,y+by)
    c[5].From=Vector2.new(x,y+h)    c[5].To=Vector2.new(x+bx,y+h)
    c[6].From=Vector2.new(x,y+h)    c[6].To=Vector2.new(x,y+h-by)
    c[7].From=Vector2.new(x+w,y+h)  c[7].To=Vector2.new(x+w-bx,y+h)
    c[8].From=Vector2.new(x+w,y+h)  c[8].To=Vector2.new(x+w,y+h-by)
    for _, ln in ipairs(c) do ln.Color = color; ln.Visible = true end
end

local VP = Camera.ViewportSize
Camera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
    VP = Camera.ViewportSize
end)

local function drawSkeleton(d, char, color)
    if not Toggles.ESP_Skeleton.Value then
        for _, ln in ipairs(d.Skeleton) do ln.Visible = false end
        return
    end
    local used = 0
    for _, pair in ipairs(BONE_PAIRS) do
        local pA = char:FindFirstChild(pair[1])
        local pB = char:FindFirstChild(pair[2])
        if pA and pB then
            local spA, onA = Camera:WorldToViewportPoint(pA.Position)
            local spB, onB = Camera:WorldToViewportPoint(pB.Position)
            if onA and onB and spA.Z > 0 and spB.Z > 0 then
                used = used + 1
                local ln = d.Skeleton[used]
                ln.From = Vector2.new(spA.X, spA.Y)
                ln.To   = Vector2.new(spB.X, spB.Y)
                ln.Color = color; ln.Visible = true
            end
        end
    end
    for i = used + 1, MAX_BONES do d.Skeleton[i].Visible = false end
end

local function applyTracer(d, sp)
    if Toggles.ESP_Tracers.Value then
        d.Tracer.From    = Vector2.new(VP.X * 0.5, VP.Y)
        d.Tracer.To      = Vector2.new(sp.X, sp.Y)
        d.Tracer.Color   = Options.Color_Tracer.Value
        d.Tracer.Visible = true
    else
        d.Tracer.Visible = false
    end
end

-- ── Box sizes (increased from v2) ─────────────────────────────
local BOX = { PlayerW = 80, PlayerH = 110, DropW = 45, DropH = 45 }

local function drawBox(d, sp, w, h, topText, distText, boxColor, distColor, char)
    local x, y = sp.X - w * .5, sp.Y - h * .5
    local style = Options.ESP_BoxStyle.Value

    if Toggles.ESP_Boxes.Value and style ~= "Dot Only" then
        d.Outline.Size     = Vector2.new(w + 3, h + 3)
        d.Outline.Position = Vector2.new(x - 1.5, y - 1.5)
        d.Outline.Visible  = true
    else
        d.Outline.Visible = false
    end

    if Toggles.ESP_Boxes.Value then
        if style == "Full Box" then
            d.Box.Size = Vector2.new(w, h); d.Box.Position = Vector2.new(x, y)
            d.Box.Color = boxColor; d.Box.Visible = true
            for _, ln in ipairs(d.Corners) do ln.Visible = false end
        elseif style == "Corners" then
            d.Box.Visible = false
            drawCorners(d.Corners, x, y, w, h, boxColor)
        else
            d.Box.Visible = false
            for _, ln in ipairs(d.Corners) do ln.Visible = false end
        end
    else
        d.Box.Visible = false
        for _, ln in ipairs(d.Corners) do ln.Visible = false end
    end

    if Toggles.ESP_Names.Value and topText ~= "" then
        d.TopLabel.Text = topText; d.TopLabel.Color = boxColor
        d.TopLabel.Position = Vector2.new(sp.X, y - 16); d.TopLabel.Visible = true
    else
        d.TopLabel.Visible = false
    end

    if Toggles.ESP_Distance.Value and distText ~= "" then
        d.DistLabel.Text = distText; d.DistLabel.Color = distColor
        d.DistLabel.Position = Vector2.new(sp.X, y + h + 3); d.DistLabel.Visible = true
    else
        d.DistLabel.Visible = false
    end

    d.Dot.Visible = false
    applyTracer(d, sp)

    if char then
        drawSkeleton(d, char, Options.Color_Skeleton.Value)
    else
        for _, ln in ipairs(d.Skeleton) do ln.Visible = false end
    end
end

local function drawDot(d, sp, boxColor, distText, distColor)
    d.Outline.Visible  = false; d.Box.Visible      = false
    d.TopLabel.Visible = false
    for _, ln in ipairs(d.Corners)  do ln.Visible = false end
    for _, ln in ipairs(d.Skeleton) do ln.Visible = false end

    d.Dot.Position = Vector2.new(sp.X, sp.Y)
    d.Dot.Color = boxColor; d.Dot.Visible = true

    if Toggles.ESP_Distance.Value and distText ~= "" then
        d.DistLabel.Text = distText; d.DistLabel.Color = distColor
        d.DistLabel.Position = Vector2.new(sp.X, sp.Y + 7); d.DistLabel.Visible = true
    else
        d.DistLabel.Visible = false
    end

    applyTracer(d, sp)
end

