Players.PlayerRemoving:Connect(removePlayerESP)

local dropESP = {}

local function isGunDrop(v) return v.Name == "GunDrop" and v:IsA("BasePart") end

local function addDropESP(part)
    if dropESP[part] then return end
    dropESP[part] = newESPData()
    part.AncestryChanged:Connect(function()
        if not part:IsDescendantOf(workspace) then
            if dropESP[part] then removeESPData(dropESP[part]); dropESP[part] = nil end
        end
    end)
end

for _, v in ipairs(workspace:GetDescendants()) do
    if isGunDrop(v) then addDropESP(v) end
end
workspace.DescendantAdded:Connect(function(v)
    if isGunDrop(v) then addDropESP(v) end
end)

--// ═══════════════════════════════════
--//  Autofarm  —  CoinContainer
--// ═══════════════════════════════════
local TweenService = game:GetService("TweenService")

local function log(level, msg)
    if _G.Log then _G.Log(level, msg) end
end

local function setStatus(s)
    if _G.SetDebugStatus then _G.SetDebugStatus(s) end
end

-- Coins are BaseParts inside the CoinContainer Model (at any nesting depth).
local function getCoinsFromContainer(container)
    local coins = {}

    for _, desc in ipairs(container:GetDescendants()) do
        if desc:IsA("BasePart") then
            table.insert(coins, { instance = desc, position = desc.Position })
        end
    end

    log("INFO", string.format("getCoinsFromContainer: found %d parts", #coins))
    return coins
end

-- ── CoinContainer detection via event (no polling overhead) ────
local coinContainerFound  = Instance.new("BindableEvent")
local _cachedContainer    = nil

local function findCoinContainer()
    for _, desc in ipairs(workspace:GetDescendants()) do
        if desc.Name == "CoinContainer" and desc:IsA("Model") then
            return desc
        end
    end
    return nil
end

-- Watch for CoinContainer appearing anywhere in workspace
workspace.DescendantAdded:Connect(function(desc)
    if desc.Name == "CoinContainer" and desc:IsA("Model") then
        _cachedContainer = desc
        coinContainerFound:Fire(desc)
    end
end)

-- Returns immediately if already present, otherwise yields until it appears
-- or until farm is turned off / script unloaded.
local function waitForCoinContainer()
    local container = _cachedContainer and _cachedContainer:IsDescendantOf(workspace)
        and _cachedContainer
        or findCoinContainer()

    if container then
        _cachedContainer = container
        log("FOUND", "CoinContainer at: " .. container:GetFullName())
        setStatus("Farming")
        return container
    end

    log("INFO", "Waiting for CoinContainer...")
    setStatus("Waiting for round")

    -- Yield until DescendantAdded fires OR farm is disabled
    local result = nil
    local conn
    conn = coinContainerFound.Event:Connect(function(c)
        result = c
        conn:Disconnect()
    end)

    while not result and not Library.Unloaded and Toggles.AF_Enabled.Value do
        task.wait(0.2)
    end

    if result then
        log("FOUND", "CoinContainer appeared at: " .. result:GetFullName())
        setStatus("Farming")
    else
        conn:Disconnect()
        log("WARN", "waitForCoinContainer exited — farm disabled or script unloaded")
    end

    return result
end

