-- ── TWEEN navigation ───────────────────────────────────────────
local function tweenTo(targetPos)
    local hrp = getHRP()
    if not hrp then
        log("WARN", "tweenTo: HRP missing — skipping coin")
        return
    end

    local destination = Vector3.new(targetPos.X, hrp.Position.Y, targetPos.Z)
    local distance    = (hrp.Position - destination).Magnitude
    local duration    = math.max(distance / Options.AF_TweenSpeed.Value, 0.05)

    local tween = TweenService:Create(
        hrp,
        TweenInfo.new(duration, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut),
        { CFrame = CFrame.new(destination) }
    )

    tween:Play()
    tween.Completed:Wait()
    game:GetService("RunService").Heartbeat:Wait()
end

-- ── Waypoint visualizer ────────────────────────────────────────
local waypointFolder      = Instance.new("Folder")
waypointFolder.Name       = "ESP_Waypoints"
waypointFolder.Parent     = workspace

_G.ClearWaypoints = function()
    waypointFolder:ClearAllChildren()
end

local function spawnWaypointBlock(pos, isJump)
    local p          = Instance.new("Part")
    p.Anchored       = true
    p.CanCollide     = false
    p.CastShadow     = false
    p.Size           = Vector3.new(0.55, 0.55, 0.55)
    p.CFrame         = CFrame.new(pos)
    p.Material       = Enum.Material.Neon
    p.Color          = isJump
        and Color3.fromRGB(255, 200,  0)  -- yellow = jump
        or  Color3.fromRGB(  0, 220, 80)  -- green  = walk
    p.Parent         = waypointFolder
    return p
end

-- ── Pathfinding constants ───────────────────────────────────────
local PFS = game:GetService("PathfindingService")

local PATH_PARAMS = {
    AgentRadius     = 2,
    AgentHeight     = 5,
    AgentCanJump    = true,
    AgentMaxSlope   = 60,
    WaypointSpacing = 6,   -- wider spacing = fewer edge-clip waypoints
}

local WAYPOINT_TIMEOUT = 6   -- seconds per waypoint before declaring stuck
local REACH_DIST       = 5   -- studs — how close counts as "reached"
local MAX_RETRIES      = 1

-- ── LEGIT navigation  (PathfindingService) ─────────────────────
local function walkTo(targetPos)
    local function char()  return LocalPlayer.Character end
    local function hrp()   local c = char(); return c and c:FindFirstChild("HumanoidRootPart") end
    local function hum()   local c = char(); return c and c:FindFirstChildOfClass("Humanoid") end
    local function alive() local r = hrp(); return r ~= nil and r.Parent ~= nil end

    local showWp = Toggles.Debug_Waypoints and Toggles.Debug_Waypoints.Value

    local function followPath(from, to)
        if not alive() then return "abort" end

        local path = PFS:CreatePath(PATH_PARAMS)
        local ok   = pcall(path.ComputeAsync, path, from, to)

        if not ok or path.Status ~= Enum.PathStatus.Success then
            log("WARN", "Path compute failed → direct MoveTo")
            local h = hum()
            if not h then return "abort" end
            h:MoveTo(to)
            local t0 = tick()
            repeat
                task.wait(0.1)
                if not alive() then return "abort" end
            until (hrp().Position - to).Magnitude < REACH_DIST
                or tick() - t0 > WAYPOINT_TIMEOUT * 2
                or not Toggles.AF_Enabled.Value
            return "done"
        end

        local waypoints = path:GetWaypoints()
        log("INFO", string.format("Path: %d waypoints", #waypoints))

        -- Spawn debug blocks (skip index 1 = agent start)
        local blocks = {}
        if showWp then
            _G.ClearWaypoints()
            for i = 2, #waypoints do
                blocks[i] = spawnWaypointBlock(
                    waypoints[i].Position,
                    waypoints[i].Action == Enum.PathWaypointAction.Jump
                )
            end
        end

        for i, wp in ipairs(waypoints) do
            if not Toggles.AF_Enabled.Value or Library.Unloaded then
                if showWp then _G.ClearWaypoints() end
                return "abort"
            end
            if not alive() then
                log("WARN", "Character lost mid-path")
                if showWp then _G.ClearWaypoints() end
                return "abort"
            end

            local h = hum()
            if not h then return "abort" end

            -- Jump: set true, yield two frames so engine registers it, then release
            if wp.Action == Enum.PathWaypointAction.Jump then
                h.Jump = true
                task.wait()
                task.wait()
                h.Jump = false
                -- Give the character time to leave the ground before moving on
                task.wait(0.3)
            end

            h:MoveTo(wp.Position)

            local deadline = tick() + WAYPOINT_TIMEOUT
            local reached  = false

            repeat
                task.wait(0.1)
                if not alive() then
                    log("WARN", "HRP lost mid-waypoint")
                    if showWp then _G.ClearWaypoints() end
                    return "abort"
                end
                reached = (hrp().Position - wp.Position).Magnitude < REACH_DIST
            until reached or tick() > deadline or not Toggles.AF_Enabled.Value

            if not reached then
                if showWp and blocks[i] and blocks[i].Parent then
                    blocks[i].Color = Color3.fromRGB(255, 50, 50)
                end
                log("WARN", string.format("Stuck at waypoint %d/%d", i, #waypoints))
                if showWp then task.delay(0.8, _G.ClearWaypoints) end
                return "stuck"
            end

            -- Mark visited block grey
            if showWp and blocks[i] and blocks[i].Parent then
                blocks[i].Color    = Color3.fromRGB(100, 100, 100)
                blocks[i].Material = Enum.Material.SmoothPlastic
            end
        end

        if showWp then task.delay(0.5, _G.ClearWaypoints) end
        return "done"
    end

    local r = hrp()
    if not r then log("WARN", "walkTo: no HRP at start") return end

    local result = followPath(r.Position, targetPos)

    if result == "stuck" then
        r = hrp()
        if r then
            log("INFO", "Recomputing from current position")
            result = followPath(r.Position, targetPos)
        end
    end

    if result == "stuck" then
        log("ERROR", "Still stuck after retry — skipping coin")
    end
end

-- ── Helpers ────────────────────────────────────────────────────

local function sortByDistance(coins, origin)
    table.sort(coins, function(a, b)
        return (a.position - origin).Magnitude < (b.position - origin).Magnitude
    end)
end

local function resetSpeed(hum)
    if hum then hum.WalkSpeed = 16 end
end

-- ── Main farm loop ─────────────────────────────────────────────
task.spawn(function()
    log("INFO", "Autofarm task started")

    while not Library.Unloaded do
        task.wait(0.1)

        if not Toggles.AF_Enabled.Value then
            local char = LocalPlayer.Character
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            resetSpeed(hum)
            setStatus("Idle")
            continue
        end

        local char = LocalPlayer.Character
        local hum  = char and char:FindFirstChildOfClass("Humanoid")
        local hrp  = char and char:FindFirstChild("HumanoidRootPart")

        if not hum or not hrp then
            log("WARN", "Character not ready — retrying")
            task.wait(0.5)
            continue
        end

        hum.WalkSpeed = Options.AF_WalkSpeed.Value

        -- Block until a CoinContainer appears, or farm is turned off
        local container = waitForCoinContainer()

        if not container then
            log("INFO", "Farm disabled while waiting — stopping")
            continue
        end

        if Library.Unloaded then break end

        local coins = getCoinsFromContainer(container)

        if #coins == 0 then
            log("WARN", "CoinContainer is empty — waiting")
            task.wait(1)
            continue
        end

        log("INFO", string.format("Found %d coins — mode: %s", #coins, Options.AF_Mode.Value))
        setStatus(string.format("Farming (%d coins)", #coins))

        -- Refresh HRP before sorting since position may have changed
        hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        if hrp then sortByDistance(coins, hrp.Position) end

        local collected = 0

        for _, coin in ipairs(coins) do
            if not Toggles.AF_Enabled.Value or Library.Unloaded then
                log("INFO", "Farm stopped mid-batch")
                break
            end

            -- Round ended — CoinContainer was removed from the hierarchy
            if not container:IsDescendantOf(workspace) then
                log("INFO", "CoinContainer removed — round ended, waiting for next")
                setStatus("Round ended — waiting")
                break
            end

            -- Refresh character references in case of respawn
            char = LocalPlayer.Character
            hum  = char and char:FindFirstChildOfClass("Humanoid")
            hrp  = char and char:FindFirstChild("HumanoidRootPart")

            if not hum or not hrp then
                log("WARN", "Character lost mid-batch — breaking")
                break
            end

            -- Coin may have already been collected
            if not coin.instance or not coin.instance.Parent then continue end

            local currentHRP = getHRP()
            log("INFO", string.format(
                "Going to coin %d/%d  [%.1f st]",
                collected + 1, #coins,
                currentHRP and (coin.position - currentHRP.Position).Magnitude or -1
            ))

            local ok, err = pcall(function()
                if Options.AF_Mode.Value == "TWEEN" then
                    tweenTo(coin.position)
                else
                    local h = LocalPlayer.Character
                        and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
                    if h then h.WalkSpeed = Options.AF_WalkSpeed.Value end
                    walkTo(coin.position)
                end
            end)

            if not ok then
                log("ERROR", "Navigation error: " .. tostring(err))
            else
                collected = collected + 1
                log("OK", string.format("Coin %d/%d collected", collected, #coins))
                setStatus(string.format("Farming — %d/%d", collected, #coins))
            end

            task.wait(Options.AF_CollectDelay.Value)
        end

        log("OK", string.format("Batch done — %d coins collected", collected))
        setStatus("Batch done — waiting")
        task.wait(0.5)
    end

    log("INFO", "Autofarm task ended")
end)

--// ═══════════════════════════════════
--//  Render loop
--// ═══════════════════════════════════
RunService.RenderStepped:Connect(function()
    if Toggles.ESP_FOV.Value then
        fovCircle.Position = VP * 0.5
        fovCircle.Radius   = Options.ESP_FOVRadius.Value
        fovCircle.Color    = Options.Color_FOV.Value
        fovCircle.Visible  = true
    else
        fovCircle.Visible = false
    end

    if not Toggles.ESP_Enabled.Value then
        for _, d in pairs(playerESP) do hideAll(d) end
        for _, d in pairs(dropESP)   do hideAll(d) end
        return
    end

    local myChar = LocalPlayer.Character
    local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
    if not myHRP then return end

    local myPos   = myHRP.Position
    local myTeam  = LocalPlayer.Team
    local maxDist = Options.ESP_MaxDist.Value
    local dotDist = Options.ESP_DotDist.Value

    -- Players
    for player, data in pairs(playerESP) do
        local char = player.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if not root then hideAll(data) continue end

        if Toggles.ESP_TeamCheck.Value and myTeam ~= nil and player.Team == myTeam then
            hideAll(data) continue
        end

        local dist = (root.Position - myPos).Magnitude
        if dist > maxDist then hideAll(data) continue end

        local sp, onScreen = Camera:WorldToViewportPoint(root.Position)
        if not onScreen or sp.Z <= 0 then hideAll(data) continue end

        local weapon    = getWeapon(player, char)
        local boxColor  = getBoxColor(weapon)
        local icon      = WEAPON_ICONS[weapon] or ""
        local distStr   = math.floor(dist) .. "m"
        local distColor = getDistColor(dist)
        local nameStr   = icon ~= "" and (player.DisplayName .. icon) or player.DisplayName

        if dist > dotDist or Options.ESP_BoxStyle.Value == "Dot Only" then
            drawDot(data, sp, boxColor, distStr, distColor)
        else
            local scale = 1 / (sp.Z * 0.1)
            drawBox(data, sp,
                BOX.PlayerW * scale, BOX.PlayerH * scale,
                nameStr, distStr, boxColor, distColor, char)
        end
    end

    -- Gun Drops
    if Toggles.Drop_Enabled.Value then
        local dropMax   = Options.Drop_MaxDist.Value
        local dropColor = getBoxColor("GunDrop")

        for part, data in pairs(dropESP) do
            if not part or not part.Parent then hideAll(data) continue end

            local dist = (part.Position - myPos).Magnitude
            if dist > dropMax then hideAll(data) continue end

            local sp, onScreen = Camera:WorldToViewportPoint(part.Position)
            if not onScreen or sp.Z <= 0 then hideAll(data) continue end

            local distStr   = math.floor(dist) .. "m"
            local distColor = getDistColor(dist)
            local label     = Toggles.Drop_Distance.Value and distStr or ""

            if dist > dotDist then
                drawDot(data, sp, dropColor, label, distColor)
            else
                local scale = 1 / (sp.Z * 0.1)
                drawBox(data, sp,
                    BOX.DropW * scale, BOX.DropH * scale,
                    "🟠 DROP", label, dropColor, distColor, nil)
            end
        end
    else
        for _, d in pairs(dropESP) do hideAll(d) end
    end
end)

--// ═══════════════════════════════════
--//  Unload cleanup
--// ═══════════════════════════════════
Library:OnUnload(function()
    local char = LocalPlayer.Character
    local hum  = char and char:FindFirstChildOfClass("Humanoid")
    if hum then hum.WalkSpeed = 16 end
    fovCircle:Remove()
    for _, d in pairs(playerESP) do removeESPData(d) end
    for _, d in pairs(dropESP)   do removeESPData(d) end
    playerESP = {}; dropESP = {}
end)

